import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Day04 · The runtime takes shape","description":"","frontmatter":{"title":"Day04 · The runtime takes shape","outline":false},"headers":[],"relativePath":"en/log/day-04.md","filePath":"en/log/day-04.md","lastUpdated":1794015952000}'),r={name:"en/log/day-04.md"};function n(i,t,s,c,l,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<p>On 2026-11-06 Hearth grew from the stage-one MVP into a full local Agent OS. That day 102 commits touched 432 files (+35,228/−4,327), moving the chat-first interface, native agent runtime, four model protocols, sources and document extraction, local outbox, Windows desktop helper, proactive service, memory, method evolution, incremental sync, leases, kill switch, encrypted backup, health maintenance, and redacted diagnostics into running code with automated tests.</p><p>The day did not treat &quot;the page exists&quot; as closure: server, API, projection, executor boundary, and tests landed together. The suite grew from 51 tests to 40 test files and 198 tests; <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run docs:build</code> all passed. Phases 2–6 still count as partial, not because code is missing, but because real accounts, real devices, and long-running acceptance are still outstanding.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Chat-first interface</td><td>Rebuilt the web app around conversation, with tasks, proposals, approvals, and artifacts organised around the thread</td></tr><tr><td>Native agent runtime</td><td>Single-agent tool loop, four budget classes, tool permissions, checkpoints, wait-for-input and resume, and recovery of missing artifacts</td></tr><tr><td>Four model protocols</td><td>OpenAI Chat, OpenAI Responses, Anthropic Messages, and Gemini unified as streaming agent turns</td></tr><tr><td>Two executors</td><td><code>native</code> and <code>codex</code> sit side by side; executor identity is written into the run manifest and failures never switch silently</td></tr><tr><td>Sources and documents</td><td>Local files, knowledge base, web pages, and TXT/Markdown/CSV/JSON/HTML/PDF/DOCX/XLSX extraction with source entries</td></tr><tr><td>Local outbox</td><td>Drafts, one-time approval, write to the local outbox after approval, and stored receipts</td></tr><tr><td>Windows desktop</td><td>Six-digit pairing, per-capability approval, observation, pause/takeover/hand-back, low-risk input, UIA invoke, and UWP window attribution</td></tr><tr><td>Proactive service</td><td>Six trigger classes, a proactive inbox, accept/ignore/snooze/convert-to-task, and an attention budget</td></tr><tr><td>Memory and methods</td><td>Memory candidates, recall, correction, conflict, forgetting, and export; method candidates, trial evidence, evaluation, promotion, rejection, and rollback</td></tr><tr><td>Multi-device and safety</td><td>Incremental event sync, peer authentication, task leases with epoch fencing, device revocation, token rotation, and a global kill switch</td></tr><tr><td>Backup and operations</td><td>AES-256-GCM encrypted backup, rollback restore, health snapshots, periodic maintenance, and redacted diagnostics</td></tr></tbody></table><h2 id="verification-baseline" tabindex="-1">Verification baseline <a class="header-anchor" href="#verification-baseline" aria-label="Permalink to &quot;Verification baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Tests</td><td><code>npm test</code> passed 40 test files and 198 tests</td></tr><tr><td>Types</td><td><code>npm run typecheck</code> passed</td></tr><tr><td>Web build</td><td><code>npm run build</code> passed</td></tr><tr><td>Docs build</td><td><code>npm run docs:build</code> passed</td></tr><tr><td>Real tasks</td><td>Stage-one acceptance still stands: 15 tasks ran, 13 passed; the T07/T08 boundaries are unchanged</td></tr><tr><td>Evidence rule</td><td>Code closure was not written up as real acceptance; external comments and desktop actions were not described as completed</td></tr></tbody></table><blockquote><p>This log records implementation and internal verification, not a v1.0 release. Real accounts, real devices, long-running operation, and failure drills for phases 2–6 remain governed by <a href="/hearth-os/en/delivery/status.html">delivery status</a>.</p></blockquote><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>a0544fd</code></td><td>JasonBuildAI</td><td>Added the Simple Pro read model to prepare aggregated task, approval, and artifact views for the chat-first interface; 8 files (+729/−21).</td></tr><tr><td><code>b748d02</code></td><td>JasonBuildAI</td><td>Converged the interface on the Simple Pro structure and removed the older complex control-plane layout; 32 files (+2,970/−1,360).</td></tr><tr><td><code>3aca641</code></td><td>JasonBuildAI</td><td>Rebuilt the web app as a chat-first interface organised around conversation, tasks, proposals, and approvals; 9 files (+1,288/−357).</td></tr><tr><td><code>8d28901</code></td><td>JasonBuildAI</td><td>Added the source registry store, recording source type, status, read time, and errors; 3 files (+198/−1).</td></tr><tr><td><code>cec6d41</code></td><td>JasonBuildAI</td><td>Added source-reading APIs for local files, knowledge base, and web sources, with incremental refresh; 5 files (+735/−2).</td></tr><tr><td><code>b408eb3</code></td><td>JasonBuildAI</td><td>Added document extraction for TXT, Markdown, CSV, JSON, HTML, PDF, DOCX, and XLSX, including page, sheet, and range records; 6 files (+3,461/−74).</td></tr><tr><td><code>d458bd3</code></td><td>JasonBuildAI</td><td>Added a source picker to the new-task flow so ready source entries can be attached to a task; 4 files (+180/−6).</td></tr><tr><td><code>ae5bf0f</code></td><td>JasonBuildAI</td><td>Added the outbox draft projection, showing drafts, submission status, and receipts; 3 files (+152/−2).</td></tr><tr><td><code>b820dca</code></td><td>JasonBuildAI</td><td>Added outbox draft APIs for editing, saving, discarding, and submitting for approval; 6 files (+551/−1).</td></tr><tr><td><code>f1558a9</code></td><td>JasonBuildAI</td><td>Wrote approved drafts to the local outbox with stored receipts, and synchronised draft state on rejection or expiry; 4 files (+408/−4).</td></tr><tr><td><code>5b6e50f</code></td><td>JasonBuildAI</td><td>Added the Windows desktop helper with window observation, focus, click, text input, keys, and UIA actions; 1 file (+358).</td></tr><tr><td><code>34877a0</code></td><td>JasonBuildAI</td><td>Bound observation frames to the target application and rejected silently treating the host window as the approved app; 3 files (+92/−15).</td></tr><tr><td><code>97d0f07</code></td><td>JasonBuildAI</td><td>Resolved UWP host windows to their UIA child process and mapped them to the approved app, such as CalculatorApp to calculator; 1 file (+109/−17).</td></tr><tr><td><code>119b67f</code></td><td>JasonBuildAI</td><td>Recorded UWP and UIA isolation verification, including calculator invoke and the observe → act → auto-observe chain; 2 files (+6/−6).</td></tr><tr><td><code>11a1e60</code></td><td>JasonBuildAI</td><td>Added the proactive trigger engine covering deadline windows, failure or recoverability, uncertain results, pending approval, new sources, and queue backlog; 5 files (+1,144/−1).</td></tr><tr><td><code>66ee76c</code></td><td>JasonBuildAI</td><td>Added the proactive inbox and attention budget with accept, ignore, snooze, and convert-to-task; 8 files (+624/−1).</td></tr><tr><td><code>21d1592</code></td><td>JasonBuildAI</td><td>Added memory core and recall, recording provenance, confidence, sensitivity, version, and recall audits; 7 files (+1,170/−3).</td></tr><tr><td><code>ac92758</code></td><td>JasonBuildAI</td><td>Added memory browse, correction, conflict, and forgetting; forgetting redacts historical versions and recall audits; 6 files (+599/−1).</td></tr><tr><td><code>11b0307</code></td><td>JasonBuildAI</td><td>Added memory-poisoning boundary tests so memory cannot act as an instruction that widens permissions; 1 file (+21).</td></tr><tr><td><code>b6b3f63</code></td><td>JasonBuildAI</td><td>Added the method evaluation engine, recording baseline and trial success rate, duration, tokens, and approval count; 5 files (+788).</td></tr><tr><td><code>0e3a35f</code></td><td>JasonBuildAI</td><td>Added method evolution browsing with candidate generation, evaluation, promotion, rejection, and rollback; 6 files (+493/−1).</td></tr><tr><td><code>724e784</code></td><td>JasonBuildAI</td><td>Added incremental event sync and peer authentication, pulling by sequence, deduplicating, and rebuilding projections; 7 files (+816/−5).</td></tr><tr><td><code>24c2ea4</code></td><td>JasonBuildAI</td><td>Put task execution under TTL, owner, and epoch leases; expired takeover advances the epoch and stale-owner writes are rejected; 7 files (+391/−7).</td></tr><tr><td><code>e70b0d3</code></td><td>JasonBuildAI</td><td>Added the global kill switch, device revocation, token rotation, and safety audit; 14 files (+678/−22).</td></tr><tr><td><code>44f58b9</code></td><td>JasonBuildAI</td><td>Added AES-256-GCM encrypted backup and rollback restore, validating schema, user_version, and integrity_check; 16 files (+1,160/−22).</td></tr><tr><td><code>b3cffeb</code></td><td>JasonBuildAI</td><td>Added runtime health snapshots, periodic maintenance, and redacted diagnostics, marking degraded when maintenance fails; 15 files (+974/−29).</td></tr><tr><td><code>42d8827</code></td><td>JasonBuildAI</td><td>Recorded phase 4–6 delivery status, separating implemented, verified, and still-open items; 13 files (+124/−12).</td></tr><tr><td><code>32f0b0d</code></td><td>JasonBuildAI</td><td>Unified four model protocols: OpenAI Chat, OpenAI Responses, Anthropic Messages, and Gemini; 5 files (+665/−74).</td></tr><tr><td><code>581bc44</code></td><td>JasonBuildAI</td><td>Let chat answer material questions first instead of dispatching every input directly as a task; 3 files (+61/−19).</td></tr><tr><td><code>e4eefbb</code></td><td>JasonBuildAI</td><td>Added the single-agent loop with budgets and checkpoints; 5 files (+396).</td></tr><tr><td><code>99392ea</code></td><td>JasonBuildAI</td><td>Added permission-bound built-in tools for read/write, search, shell, web, asking the user, and completion; 2 files (+589).</td></tr><tr><td><code>9a37e78</code></td><td>JasonBuildAI</td><td>Added executor, permission, budget, and checkpoint contracts; 1 file (+58).</td></tr><tr><td><code>375ff8d</code></td><td>JasonBuildAI</td><td>Added the executor registry so native and codex are peers; 1 file (+33).</td></tr><tr><td><code>bbbbfab</code></td><td>JasonBuildAI</td><td>Added the native agent executor adapter connecting the runtime to the scheduler; 3 files (+168).</td></tr><tr><td><code>5f5009a</code></td><td>JasonBuildAI</td><td>Required tasks needing network or engineering-workspace permission to produce a chat proposal before dispatch; 2 files (+79/−5).</td></tr><tr><td><code>6b4295d</code></td><td>JasonBuildAI</td><td>Collected answers inline when a task waits for input, then resumed execution; 2 files (+53/−4).</td></tr><tr><td><code>c776d2c</code></td><td>JasonBuildAI</td><td>Recorded the native runtime closure, explaining executor, protocol, tools, budgets, and recovery boundaries; 2 files (+24/−2).</td></tr><tr><td><code>b5a785f</code></td><td>JasonBuildAI</td><td>Derived health expectations from the current schema version to stop test drift after upgrades; 2 files (+4/−4).</td></tr></tbody></table><h2 id="boundaries-and-next-step" tabindex="-1">Boundaries and next step <a class="header-anchor" href="#boundaries-and-next-step" aria-label="Permalink to &quot;Boundaries and next step&quot;">​</a></h2><ul><li>The phase 2–6 code closures run, but real mail/calendar accounts, high-risk desktop actions, the phone entry point, memory production comparisons, two-device switching, and long-running operation are not yet accepted.</li><li>The chat-first primary navigation only exposes chat, tasks, devices, and settings; memory, methods, sync, safety, and operations have APIs and page components that are not yet wired back into primary navigation.</li><li>The next stage does not add more pages. It closes real evidence item by item along the <a href="/hearth-os/en/delivery/">delivery route</a>.</li></ul>',11)])])}const f=e(r,[["render",n]]);export{h as __pageData,f as default};
